import datetime
try:
    HOL = set(['2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01'])
    WD = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']
    MO = ['January','February','March','April','May','June','July','August','September','October','November','December']
    now = str(vars.get('now') or '2026-10-14T11:00')
    today = datetime.date.fromisoformat(now[:10])
    hhmm = now[11:16] if len(now) >= 16 else '11:00'
    def isbd(d):
        return d.weekday() < 5 and d.isoformat() not in HOL
    def nbd(d):
        while not isbd(d):
            d = d + datetime.timedelta(days=1)
        return d
    def nth_bd(n):
        d = today; c = 0
        while c < n:
            d = d + datetime.timedelta(days=1)
            if isbd(d):
                c += 1
        return d
    def words(d):
        return WD[d.weekday()] + ' ' + str(d.day) + ' ' + MO[d.month-1]
    def lab(d):
        return d.isoformat() + ' (' + words(d) + ')'
    dl = {'early': nth_bd(12), 'late': nth_bd(7)}
    mon = today - datetime.timedelta(days=today.weekday())
    def last_bd_week(m):
        d = m + datetime.timedelta(days=4)
        while not isbd(d):
            d = d - datetime.timedelta(days=1)
        return d
    lw = last_bd_week(mon)
    if lw <= today:
        a1 = last_bd_week(mon + datetime.timedelta(days=7))
    else:
        a1 = lw
    lines = []
    lines.append('TODAY: ' + lab(today) + ', time now ' + hhmm + '. Today is ' + ('a business day.' if isbd(today) else 'not a business day.'))
    lines.append('TOMORROW = ' + lab(today + datetime.timedelta(days=1)) + '; DAY AFTER TOMORROW = ' + lab(today + datetime.timedelta(days=2)))
    for i in range(7):
        lines.append('"this ' + WD[i] + '" = ' + lab(mon + datetime.timedelta(days=i)) + ' ; "next ' + WD[i] + '" = ' + lab(mon + datetime.timedelta(days=7+i)))
    lines.append('"end of this week" = ' + lab(lw) + ' ; "next week" and "end of the month" and "salary day" are vague -> ask once for the exact day.')
    lines.append('DEADLINE early band (1-7 days late) = ' + lab(dl['early']) + ' ; DEADLINE late band (8-45 days late) = ' + lab(dl['late']))
    lines.append('ATTEMPT 1 DATE (all bands) = ' + lab(a1))
    lines.append('')
    lines.append('DAY TABLE. Find the day the customer named and do exactly what the column of the product band says:')
    end = max(dl.values()) + datetime.timedelta(days=30)
    d = today - datetime.timedelta(days=3)
    while d <= end:
        parts = []
        for b in ['early','late']:
            D = dl[b]
            if d < today:
                s = 'in the past -> not possible, ask for today or later'
            elif d > D:
                s = 'after the deadline -> say the latest date you can record is ' + words(D) + ' and offer it'
            elif isbd(d):
                s = 'OK -> use ' + d.isoformat()
            else:
                n = nbd(d)
                why = 'bank holiday' if d.isoformat() in HOL else 'weekend'
                if n > D:
                    s = why + ' and next business day is after the deadline -> offer ' + words(D) + ' (' + D.isoformat() + ')'
                else:
                    s = why + ' -> not possible, offer next business day ' + words(n) + ' (' + n.isoformat() + ')'
            parts.append(b + ': ' + s)
        lines.append(lab(d) + ' | ' + ' | '.join(parts))
        d = d + datetime.timedelta(days=1)
    vars['date_table'] = '\n'.join(lines)
    nb = nbd(today + datetime.timedelta(days=1))
    vars['callback_facts'] = 'Callback allowed only: today ' + lab(today) + ' at a time later than ' + hhmm + ' and from 10:00 to 19:00 inclusive (only if today is a business day: ' + ('yes' if isbd(today) else 'no') + '), or the next business day ' + lab(nb) + ' from 10:00 to 19:00 inclusive. "Tomorrow morning around eleven" = ' + (today + datetime.timedelta(days=1)).isoformat() + ' 11:00 (allowed only if that is ' + nb.isoformat() + '). Anything else is outside the window.'
except Exception as e:
    vars['date_table'] = 'Date table unavailable. Today is ' + str(vars.get('now'))
    vars['callback_facts'] = 'Callback today or the next business day 10:00-19:00.'

